#[derive(Debug, Clone)]
pub struct AgentConfig { pub workspace:PathBuf,pub model:String,pub max_iterations:u32,pub auto_approve:bool,pub max_context_tokens:usize,pub session_path:Option<PathBuf>,pub verification_commands:Vec<String>,pub verification_timeout_ms:u64,pub hooks_enabled:bool,pub mode:AgentMode }
impl Default for AgentConfig{fn default()->Self{Self{workspace:std::env::current_dir().unwrap_or_else(|_|PathBuf::from(".")),model:"default".into(),max_iterations:20,auto_approve:false,max_context_tokens:12000,session_path:None,verification_commands:vec!["git diff --check".into()],verification_timeout_ms:120_000,hooks_enabled:false,mode:AgentMode::Normal}}}

pub struct AgentRuntime<P:ModelProvider>{pub snapshot:AgentSnapshot,pub config:AgentConfig,pub provider:Arc<P>,pub tools:ToolRegistry,pub executor:ToolExecutor,pub policy:Policy,pub context:MessageContext,pub session:Session,pub orchestration:Orchestrator,pub verification:VerificationPlan,pub verifier:VerificationEngine,pub events:EventBus,pub approvals:ApprovalBroker,pub cancel:watch::Sender<bool>,interactive_approvals:bool}
impl<P:ModelProvider+'static> AgentRuntime<P>{
 pub fn new(goal:impl Into<String>,config:AgentConfig,provider:P)->Self{Self::new_shared(goal,config,Arc::new(provider))}
 pub fn new_shared(goal:impl Into<String>,config:AgentConfig,provider:Arc<P>)->Self{let goal=goal.into();let mut orchestration=Orchestrator::default();orchestration.install_defaults();if let Ok(skills)=discover_skills(&config.workspace){for skill in skills{orchestration.register_skill(skill);}}let verification=Self::verification_plan(&config);let tools=ToolRegistry::builtins();let executor=ToolExecutor::new(tools.clone(),config.workspace.clone());let verifier=VerificationEngine::new(config.workspace.clone(),Duration::from_millis(config.verification_timeout_ms));let(approvals,_)=ApprovalBroker::new(32);let(cancel,_)=watch::channel(false);Self{snapshot:AgentSnapshot::new(goal.clone(),config.max_iterations),session:Session::new(goal),provider,tools,executor,policy:Policy::default(),context:MessageContext::default(),config,orchestration,verification,verifier,events:EventBus::default(),approvals,cancel,interactive_approvals:false}}
 pub fn subscribe(&self)->tokio::sync::broadcast::Receiver<AgentEvent>{self.events.subscribe()}
 pub fn enable_interactive_approvals(&mut self)->tokio::sync::mpsc::Receiver<ApprovalRequest>{let(broker,receiver)=ApprovalBroker::new(32);self.approvals=broker;self.interactive_approvals=true;receiver}
 pub fn resolve_approval(&self,call_id:Uuid,approved:bool)->bool{self.approvals.resolve(call_id,approved)}
 pub fn cancel(&self){let _=self.cancel.send(true);}
 pub fn is_cancelled(&self)->bool{*self.cancel.borrow()}
 pub async fn run_subagents(&mut self,specs:Vec<SubagentSpec>,manager_config:AgentManagerConfig)->Result<Vec<SubagentResult>>{for spec in &specs{self.emit(AgentEvent::SubagentStarted{agent_id:spec.id.clone(),role:format!("{:?}",spec.role),session_id:SessionId(self.snapshot.session_id)});}let manager=AgentManager::new(self.provider.clone(),self.config.workspace.clone(),self.config.clone(),manager_config);let results=manager.run_parallel(specs).await?;for result in &results{let summary=if result.success{result.output.clone()}else{format!("failed after {} iterations: {}",result.iterations,result.output)};self.emit(AgentEvent::SubagentFinished{agent_id:result.id.clone(),success:result.success,summary});}Ok(results)}
 fn verification_plan(config:&AgentConfig)->VerificationPlan{let mut p=VerificationPlan::default();for c in &config.verification_commands{p.push(VerificationStep{kind:Self::kind_for_command(c),description:format!("verify: {c}"),command:Some(c.clone()),required:true});}p}
 fn kind_for_command(c:&str)->VerificationKind{if c.contains("git diff"){VerificationKind::GitDiff}else if c.contains("test")||c.contains("pytest")||c.contains("nextest"){VerificationKind::Test}else if c.contains("build")||c.contains("cargo check"){VerificationKind::Build}else{VerificationKind::Command}}
 async fn git_head(&self)->Option<String>{Command::new("git").args(["rev-parse","HEAD"]).current_dir(&self.config.workspace).output().await.ok().filter(|o|o.status.success()).map(|o|String::from_utf8_lossy(&o.stdout).trim().to_owned()).filter(|v|!v.is_empty())}
 async fn checkpoint(&mut self,note:&str)->Result<()>{let head=self.git_head().await;let id=self.session.checkpoint_with_git(note,head,None);self.emit(AgentEvent::CheckpointCreated{id,note:note.into()});if let Some(path)=&self.config.session_path{self.session.save_to(path).await?;}Ok(())}
 fn emit(&mut self,event:AgentEvent){self.session.append(event.clone());let _=self.events.emit(event);}
 async fn cancel_and_finish(&mut self,note:&str)->Result<String>{if !self.snapshot.state.is_terminal(){self.snapshot.transition(AgentState::Cancelled)?;}self.snapshot.last_error=Some(note.into());self.emit(AgentEvent::Error{message:note.into()});self.emit(AgentEvent::SessionFinished{success:false});self.checkpoint(note).await?;Ok(String::new())}
 async fn run_hooks(&mut self,event:HookEvent)->Result<()>{if !self.config.hooks_enabled{return Ok(());}let hooks=self.orchestration.hooks(event).cloned().collect::<Vec<_>>();for hook in hooks{let decision=self.policy.decide_for(Operation::Shell,&hook.command);let allowed=matches!(decision,Decision::Allow)||(matches!(decision,Decision::Ask)&&self.config.auto_approve);if !allowed{self.emit(AgentEvent::Error{message:format!("hook '{}' skipped: shell permission {:?}",hook.name,decision)});continue;}let mut cmd=Command::new(if cfg!(windows){"cmd"}else{"sh"});cmd.args(if cfg!(windows){vec!["/C",hook.command.as_str()]}else{vec!["-lc",hook.command.as_str()]}).current_dir(&self.config.workspace);match timeout(Duration::from_millis(self.config.verification_timeout_ms),cmd.output()).await{Ok(Ok(o)) if o.status.success()=>self.emit(AgentEvent::StateChanged{state:format!("hook:{}:ok",hook.name)}),Ok(Ok(o))=>self.emit(AgentEvent::Error{message:format!("hook '{}' failed: exit={} stderr={}",hook.name,o.status.code().unwrap_or(-1),String::from_utf8_lossy(&o.stderr))}),Ok(Err(e))=>self.emit(AgentEvent::Error{message:format!("hook '{}' spawn failed: {e}",hook.name)}),Err(_)=>self.emit(AgentEvent::Error{message:format!("hook '{}' timed out",hook.name)})}}Ok(())}
 async fn verify(&mut self)->Result<bool>{let result=self.verifier.run(&self.verification).await?;self.emit(AgentEvent::Verification{passed:result.passed,summary:result.summary.clone()});self.context.push("verification",result.summary);Ok(result.passed)}
 fn skill_prompt(&self)->String{format!("Available X11 Code operating skills:\n{}",self.orchestration.skills().map(|s|format!("### {}\n{}\nTools: {}",s.name,s.instructions,s.tool_hints.join(", "))).collect::<Vec<_>>().join("\n\n"))}
 fn project_prompt(&self)->String{match load_agents_md(&self.config.workspace){Ok(info) if !info.text.is_empty()=>format!("Project instructions discovered from AGENTS.md files:\n{}",info.text),_=>"No AGENTS.md project instructions were discovered.".into()}}
 async fn request_approval(&mut self,call_id:Uuid,tool:String,reason:String)->Result<bool>{self.emit(AgentEvent::ApprovalRequested{call_id,tool:tool.clone(),reason:reason.clone()});let approved=self.approvals.request(ApprovalRequest{call_id,tool:tool.clone(),reason}).await?;self.emit(AgentEvent::ApprovalResolved{call_id,tool,approved});Ok(approved)}
 pub async fn run(&mut self)->Result<String>{self.run_hooks(HookEvent::BeforeRun).await?;self.emit(AgentEvent::SessionStarted{session_id:SessionId(self.snapshot.session_id)});self.snapshot.transition(AgentState::Planning)?;self.context.push("system",self.system_prompt());self.context.push("system",self.project_prompt());self.context.push("system",self.skill_prompt());self.context.push("system",format!("Execution mode: {:?}. Plan mode is strictly read-only; Review mode is strictly non-mutating.",self.config.mode));self.context.push("user",self.snapshot.goal.clone());self.checkpoint("run started").await?;for _ in 0..self.snapshot.max_iterations{if self.is_cancelled(){return self.cancel_and_finish("run cancelled").await;}self.snapshot.iteration+=1;self.snapshot.transition(AgentState::Executing)?;self.emit(AgentEvent::StateChanged{state:"executing".into()});self.context.compact(self.config.max_context_tokens);let request=CompletionRequest{model:self.config.model.clone(),messages:self.context.to_messages(),tools:self.tools.definitions(),temperature:Some(0.1),max_tokens:Some(8192)};let mut cancel_rx=self.cancel.subscribe();let completion=self.provider.complete(request);tokio::pin!(completion);let response=tokio::select!{result=&mut completion=>result.context("model completion failed")?,changed=cancel_rx.changed()=>{if changed.is_err()||*cancel_rx.borrow(){return self.cancel_and_finish("cancelled while waiting for model").await;}continue;}};if !response.text.is_empty()||!response.tool_calls.is_empty(){self.context.push_assistant_message(response.text.clone(),response.tool_calls.clone());if !response.text.is_empty(){self.emit(AgentEvent::AssistantDelta{text:response.text.clone()});}}if response.tool_calls.is_empty(){self.snapshot.transition(AgentState::Verifying)?;let ok=self.verify().await?;if ok&&!response.text.is_empty(){self.snapshot.transition(AgentState::Completed)?;self.emit(AgentEvent::SessionFinished{success:true});self.run_hooks(HookEvent::AfterRun).await?;self.checkpoint("run completed").await?;return Ok(response.text)}if response.text.is_empty(){self.snapshot.last_error=Some("empty model response".into());self.emit(AgentEvent::Error{message:"empty model response".into()});self.snapshot.transition(AgentState::Failed)?;self.emit(AgentEvent::SessionFinished{success:false});self.run_hooks(HookEvent::OnError).await?;self.checkpoint("run failed").await?;anyhow::bail!("model returned an empty response")}self.snapshot.last_error=Some("verification failed".into());self.emit(AgentEvent::Error{message:"verification failed".into()});self.snapshot.transition(AgentState::Planning)?;self.context.push("system","Verification failed. Inspect verification output, repair the root cause, and verify again.");self.checkpoint("verification failed").await?;continue;}for call in response.tool_calls{if self.is_cancelled(){return self.cancel_and_finish("run cancelled before tool execution").await;}let id=Uuid::parse_str(&call.id).unwrap_or_else(|_|Uuid::new_v4());self.emit(AgentEvent::ToolRequested{call_id:id,tool:call.name.clone(),input:call.arguments.clone()});self.run_hooks(HookEvent::BeforeTool).await?;let tool=self.tools.get(&call.name).ok_or_else(||anyhow::anyhow!("unknown tool: {}",call.name))?;let op=match tool.kind(){ToolKind::ReadOnly=>Operation::Read,ToolKind::FilesystemWrite=>Operation::FilesystemWrite,ToolKind::Shell=>Operation::Shell,ToolKind::GitWrite=>Operation::GitWrite,ToolKind::Network=>Operation::Network};if !self.config.mode.allows_writes()&&matches!(op,Operation::FilesystemWrite|Operation::GitWrite){let out="write denied by execution mode".to_string();self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:false});self.context.push_tool_result(id.to_string(),out.clone());self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:false,output:out});continue;}if !self.config.mode.allows_shell()&&matches!(op,Operation::Shell){let out="shell denied by execution mode".to_string();self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:false});self.context.push_tool_result(id.to_string(),out.clone());self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:false,output:out});continue;}let subject=match op{Operation::Shell=>call.arguments["command"].as_str().unwrap_or(""),Operation::GitWrite=>call.arguments["args"].as_array().map(|a|a.iter().filter_map(|v|v.as_str()).collect::<Vec<_>>().join(" ")).unwrap_or_default(),Operation::FilesystemWrite|Operation::Read=>call.arguments["path"].as_str().unwrap_or(""),Operation::Network=>call.name.clone()};let decision=self.policy.decide_for(op,&subject);let allowed=match decision{Decision::Allow=>true,Decision::Deny=>false,Decision::Ask=>{if self.config.auto_approve{self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:true});true}else if self.interactive_approvals{self.request_approval(id,call.name.clone(),format!("permission required for {op:?}")).await?}else{self.emit(AgentEvent::ApprovalRequested{call_id:id,tool:call.name.clone(),reason:"permission requires approval; rerun with --yes or --tui".into()});self.emit(AgentEvent::ApprovalResolved{call_id:id,tool:call.name.clone(),approved:false});false}}};if !allowed{let out="tool call denied by permission policy".to_string();self.context.push_tool_result(id.to_string(),out.clone());self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:false,output:out});continue;}let req=ToolExecutionRequest{call_id:id,name:call.name.clone(),arguments:call.arguments.clone(),timeout:Duration::from_millis(self.config.verification_timeout_ms.min(120_000)),max_attempts:1};let result=self.executor.execute(req,self.cancel.subscribe()).await?;if result.cancelled{return self.cancel_and_finish("run cancelled during tool execution").await;}self.context.push_tool_result(id.to_string(),result.output.clone());self.emit(AgentEvent::ToolCompleted{call_id:id,tool:call.name.clone(),success:result.success,output:result.output.clone()});if !result.success{self.emit(AgentEvent::Error{message:format!("tool {} failed after {} attempt(s): {}",call.name,result.attempts,result.output)});}self.run_hooks(HookEvent::AfterTool).await?;}self.snapshot.transition(AgentState::Verifying)?;self.emit(AgentEvent::Verification{passed:true,summary:format!("iteration {} completed; tool results returned to context",self.snapshot.iteration)});self.snapshot.transition(AgentState::Planning)?;self.checkpoint(&format!("iteration {} completed",self.snapshot.iteration)).await?;}self.snapshot.last_error=Some("iteration limit reached".into());self.snapshot.transition(AgentState::Failed)?;self.emit(AgentEvent::Error{message:"iteration limit reached".into()});self.emit(AgentEvent::SessionFinished{success:false});self.run_hooks(HookEvent::OnError).await?;self.checkpoint("iteration limit reached").await?;anyhow::bail!("agent iteration limit reached")}
 fn system_prompt(&self)->String{format!("You are X11 Code, an autonomous coding agent. Work only inside the workspace. Goal: {}\nUse tools deliberately. Inspect before editing, make narrow changes, inspect diffs after edits, and use tests or other verification commands when required. Treat every tool result as authoritative and never invent output. Workspace: {}",self.snapshot.goal,self.config.workspace.display())}
}
pub struct Agent;
impl Agent{pub fn new(goal:impl Into<String>)->Self{let _=goal;Self}}
